/**
 * Tool Call Recovery Module
 *
 * Handles recovery from malformed tool calls generated by local models.
 * Implements multiple strategies:
 * 1. Text-based tool call extraction (parse JSON/XML from text)
 * 2. Parameter inference for missing required fields
 * 3. Retry prompt generation with error feedback
 */

import { TOOL_NAME_SHAPE, TOOL_NAME_SOURCE } from "../../adapters/tool-name-utils.js";
import { log } from "../../logger.js";
import {
  type JsonSchemaNode,
  applySchemaDefaults,
  coerceToSchema,
  missingRequired,
  renameToDeclaredKeys,
} from "./schema-validate.js";

export interface ExtractedToolCall {
  name: string;
  arguments: Record<string, any>;
  source: "structured" | "json_text" | "xml_text" | "inferred";
}

export interface ToolSchema {
  name: string;
  description?: string;
  input_schema?: {
    type: string;
    properties?: Record<string, any>;
    required?: string[];
  };
}

/**
 * A tool name is an identifier, so the extractors must never accept anything else.
 *
 * Pattern 0 below used to capture `[^>]+`, which accepts every character except
 * `>`. A model that opened `<function=` in prose and closed it 80 characters
 * later had all 80 characters taken as the tool name — parameter names, type
 * fragments and ARGUMENT VALUES included. One such name reached a client:
 * `web_search_query_listOpposed["macos security add-generic-password …"]`.
 * (S4-b e82c315)
 */
const FUNCTION_TAG_SOURCE = `<function=(${TOOL_NAME_SOURCE})>([\\s\\S]*?)(?=<function=|$)`;

/** Unanchored, no `g` flag, so it holds no `lastIndex` and is safe to share. */
const FUNCTION_TAG_PRESENT = new RegExp(`<function=${TOOL_NAME_SOURCE}>`);

/**
 * Does this text hold a `<function=NAME>` tag Pattern 0 can actually extract?
 *
 * Exported so the openai-sse hold-back test uses the SAME shape the extractor
 * uses. When the two drifted, text matching the loose hold-back test but not
 * the extractor was withheld from the client and then never emitted at all: a
 * silent text loss with no tool call to show for it. Called once per streamed
 * chunk, so the pattern is built once at module load rather than per call.
 */
export function hasExtractableFunctionTag(text: string): boolean {
  return FUNCTION_TAG_PRESENT.test(text);
}

/**
 * Drop extracted calls that are not real tools.
 *
 * Three steps, and the ORDER is the design:
 *
 *  1. **Shape.** Reject a name that is not an identifier — this is how a
 *     swallowed argument value is caught. It runs on the name as it came off
 *     the WIRE.
 *  2. **Decode.** On a wire that renames tools, the model wrote the encoded
 *     name; the client's own name may legitimately differ. Decoding before
 *     step 1 would fail a name the shape rule was never about.
 *  3. **Allowlist.** Reject a well-shaped name the client never advertised —
 *     this is how a hallucinated tool is caught. The allowlist is the
 *     request's own tool list, so it is exact rather than a hardcoded roster.
 */
function keepOnlyRealTools(
  extracted: ExtractedToolCall[],
  knownToolNames?: string[],
  decodeToolName?: (name: string) => string
): ExtractedToolCall[] {
  const kept: ExtractedToolCall[] = [];
  for (const call of extracted) {
    if (!TOOL_NAME_SHAPE.test(call.name)) {
      log(
        `[ToolRecovery] Dropped extracted call: name is not an identifier: ${JSON.stringify(
          call.name.slice(0, 120)
        )}`
      );
      continue;
    }
    const decoded = decodeToolName ? decodeToolName(call.name) : call.name;
    const named = decoded === call.name ? call : { ...call, name: decoded };
    if (!knownToolNames || knownToolNames.length === 0) {
      kept.push(named);
      continue;
    }
    const canonical = knownToolNames.find((t) => t.toLowerCase() === named.name.toLowerCase());
    if (!canonical) {
      log(`[ToolRecovery] Dropped extracted call for unadvertised tool: ${named.name}`);
      continue;
    }
    kept.push(canonical === named.name ? named : { ...named, name: canonical });
  }
  return kept;
}

/** `<function=NAME>` at exactly the cursor. Sticky, so it cannot skip ahead. */
const FUNCTION_TAG_AT_CURSOR = new RegExp(`<function=(${TOOL_NAME_SOURCE})>`, "y");

/** `<parameter=NAME>` at exactly the cursor, inside a function block. */
const PARAMETER_TAG_AT_CURSOR = /<parameter=([^>\s]+)>/y;

/**
 * Parse a response that is ENTIRELY a `<function=NAME><parameter=P>V` envelope.
 *
 * Returns `null` the moment anything else appears, and that strictness is the
 * whole point: it is what makes running this BEFORE the six loose regex
 * patterns safe. Prose that merely mentions a function tag — a model explaining
 * the format, or quoting a previous turn — does not match, so it cannot
 * short-circuit anything.
 *
 * The loose Pattern 0 that still runs afterwards has a different failure mode: it
 * scans anywhere in the text, so it takes the *last* value of a repeated
 * parameter and swallows a trailing `</function>` into the value. Parsed as an
 * envelope, both are handled — the block is delimited rather than guessed at.
 *
 * Nothing here relaxes the two gates. The name must be an identifier
 * (`TOOL_NAME_SOURCE`), and the caller's own advertised tool list still filters
 * the result through `keepOnlyRealTools`. (S4-b 4a0948c)
 */
export function parseFunctionTagEnvelope(text: string): ExtractedToolCall[] | null {
  const body = text.trim();
  if (body.length === 0) return null;
  if (!body.startsWith("<function=")) return null;

  const calls: ExtractedToolCall[] = [];
  let cursor = 0;

  while (cursor < body.length) {
    FUNCTION_TAG_AT_CURSOR.lastIndex = cursor;
    const open = FUNCTION_TAG_AT_CURSOR.exec(body);
    if (!open) return null;
    cursor = FUNCTION_TAG_AT_CURSOR.lastIndex;

    const args: Record<string, any> = {};
    // Parameters, until the block ends. A block ends at `</function>`, at the
    // next `<function=`, or at the end of the text — models emit all three.
    while (cursor < body.length) {
      const rest = body.slice(cursor);
      const closeLen = /^\s*<\/function>/.exec(rest)?.[0].length;
      if (closeLen !== undefined) {
        cursor += closeLen;
        break;
      }
      if (/^\s*<function=/.test(rest)) break;

      const lead = /^\s*/.exec(rest)?.[0].length ?? 0;
      PARAMETER_TAG_AT_CURSOR.lastIndex = cursor + lead;
      const param = PARAMETER_TAG_AT_CURSOR.exec(body);
      // Anything that is not a parameter tag means this is not an envelope.
      if (!param) return null;

      let valueStart = PARAMETER_TAG_AT_CURSOR.lastIndex;
      // A newline directly after the tag is formatting, not content.
      if (body[valueStart] === "\n") valueStart += 1;

      const tail = body.slice(valueStart);
      const end = /<\/parameter>|<\/function>|<parameter=|<function=/.exec(tail);
      const raw = end ? tail.slice(0, end.index) : tail;
      args[param[1]] = raw.trim();

      cursor = valueStart + raw.length;
      const consumedClose = /^<\/parameter>/.exec(body.slice(cursor))?.[0].length;
      if (consumedClose !== undefined) cursor += consumedClose;
    }

    calls.push({ name: open[1], arguments: args, source: "xml_text" });

    const gap = /^\s*/.exec(body.slice(cursor))?.[0].length ?? 0;
    cursor += gap;
  }

  return calls.length > 0 ? calls : null;
}

/** Give one extracted call's arguments the shape its own schema declares. */
function normalizeAgainstSchema(
  call: ExtractedToolCall,
  toolSchemas?: ToolSchema[]
): ExtractedToolCall {
  const schema = toolSchemas?.find((t) => t.name === call.name)?.input_schema as
    | JsonSchemaNode
    | undefined;
  if (!schema) return call;

  const renamed = renameToDeclaredKeys(schema, call.arguments);
  const defaulted = applySchemaDefaults(schema, renamed.args);
  const coerced = coerceToSchema(schema, defaulted.args);
  if (renamed.renamed.length + defaulted.applied.length + coerced.coerced.length === 0) {
    return call;
  }
  log(
    `[ToolRecovery] Normalized ${call.name} against its schema: ` +
      `renamed=[${renamed.renamed}] defaults=[${defaulted.applied}] coerced=[${coerced.coerced}]`
  );
  return { ...call, arguments: coerced.args as Record<string, any> };
}

/**
 * Extract tool calls from text content
 * Many local models output tool calls as JSON in their text rather than using structured tool_calls
 *
 * `knownToolNames` is the tool list the client advertised on THIS request. Pass
 * it whenever it is in hand: every pattern below is then held to it, not just
 * the natural-language one.
 *
 * `decodeToolName`, when supplied, turns the name the MODEL wrote back into the
 * client's own. The model was given the renamed roster, so on a renaming wire
 * every recovered call carries a wire name that `knownToolNames` — built from
 * the client's originals — would otherwise reject in silence.
 */
export function extractToolCallsFromText(
  text: string,
  knownToolNames?: string[],
  decodeToolName?: (name: string) => string,
  toolSchemas?: ToolSchema[]
): ExtractedToolCall[] {
  // Tried FIRST, and short-circuits (S4-b 4a0948c): a response that is nothing
  // but function tags is unambiguous, and reading it as a delimited envelope
  // beats six regexes scanning for fragments of one. The envelope carries no
  // types, so every value arrives as a string and is normalized against the
  // schema the client declared.
  const envelope = parseFunctionTagEnvelope(text);
  if (envelope) {
    return keepOnlyRealTools(envelope, knownToolNames, decodeToolName).map((call) =>
      normalizeAgainstSchema(call, toolSchemas)
    );
  }

  const extracted: ExtractedToolCall[] = [];

  // Pattern 0: Qwen-style function calls <function=NAME><parameter=PARAM>VALUE
  // Example: <function=SlashCommand><parameter=command>/ls -la
  // Fresh instance per call: a `g` regex carries `lastIndex` across calls.
  const qwenPattern = new RegExp(FUNCTION_TAG_SOURCE, "gi");
  let match;
  while ((match = qwenPattern.exec(text)) !== null) {
    const funcName = match[1];
    const paramsText = match[2];
    const args: Record<string, any> = {};

    // Extract parameters: <parameter=name>value
    const paramPattern = /<parameter=([^>]+)>\s*([\s\S]*?)(?=<parameter=|<function=|$)/gi;
    let paramMatch;
    while ((paramMatch = paramPattern.exec(paramsText)) !== null) {
      const paramName = paramMatch[1];
      const paramValue = paramMatch[2].trim();
      args[paramName] = paramValue;
    }

    if (funcName) {
      extracted.push({
        name: funcName,
        arguments: args,
        source: "xml_text",
      });
      log(`[ToolRecovery] Extracted Qwen-style tool call: ${funcName}`);
    }
  }

  // Pattern 1: XML-style tool calls <tool_call>{"name": "...", "arguments": {...}}</tool_call>
  const xmlPattern = /<tool_call>\s*(\{[\s\S]*?\})\s*<\/tool_call>/gi;
  while ((match = xmlPattern.exec(text)) !== null) {
    try {
      const parsed = JSON.parse(match[1]);
      if (parsed.name) {
        extracted.push({
          name: parsed.name,
          arguments: parsed.arguments || parsed.input || parsed.parameters || {},
          source: "xml_text",
        });
      }
    } catch (e) {
      // Continue trying other patterns
    }
  }

  // Pattern 2: Function call format {"name": "tool_name", "arguments": {...}}
  const funcCallPattern =
    /\{\s*"name"\s*:\s*"([^"]+)"\s*,\s*"(?:arguments|input|parameters)"\s*:\s*(\{[\s\S]*?\})\s*\}/gi;
  while ((match = funcCallPattern.exec(text)) !== null) {
    try {
      const args = JSON.parse(match[2]);
      extracted.push({
        name: match[1],
        arguments: args,
        source: "json_text",
      });
    } catch (e) {
      // Continue
    }
  }

  // Pattern 2b: Alternative format {"tool": "tool_name", "tool_input": {...}}
  // Some models (like Qwen) output this format instead
  const toolInputPattern =
    /\{\s*"tool"\s*:\s*"([^"]+)"\s*,\s*"tool_input"\s*:\s*(\{[\s\S]*?\})\s*\}/gi;
  while ((match = toolInputPattern.exec(text)) !== null) {
    try {
      const args = JSON.parse(match[2]);
      extracted.push({
        name: match[1],
        arguments: args,
        source: "json_text",
      });
      log(`[ToolRecovery] Extracted tool/tool_input format: ${match[1]}`);
    } catch (e) {
      // Continue
    }
  }

  // Pattern 3: Anthropic-style tool_use blocks in text
  const anthropicPattern =
    /\{\s*"type"\s*:\s*"tool_use"\s*,\s*"id"\s*:\s*"[^"]*"\s*,\s*"name"\s*:\s*"([^"]+)"\s*,\s*"input"\s*:\s*(\{[\s\S]*?\})\s*\}/gi;
  while ((match = anthropicPattern.exec(text)) !== null) {
    try {
      const args = JSON.parse(match[2]);
      extracted.push({
        name: match[1],
        arguments: args,
        source: "json_text",
      });
    } catch (e) {
      // Continue
    }
  }

  // Pattern 3b: OpenAI tool_call format in array
  // [{"type":"tool_call","id":"...","tool_call":{"name":"...","arguments":{...}}}]
  const openaiArrayPattern =
    /\{\s*"type"\s*:\s*"tool_call"\s*,\s*"id"\s*:\s*"[^"]*"\s*,\s*"tool_call"\s*:\s*\{\s*"name"\s*:\s*"([^"]+)"\s*,\s*"arguments"\s*:\s*(\{[\s\S]*?\})\s*\}\s*\}/gi;
  while ((match = openaiArrayPattern.exec(text)) !== null) {
    try {
      const args = JSON.parse(match[2]);
      extracted.push({
        name: match[1],
        arguments: args,
        source: "json_text",
      });
      log(`[ToolRecovery] Extracted OpenAI tool_call format: ${match[1]}`);
    } catch (e) {
      // Continue
    }
  }

  // Pattern 4: Simple JSON objects that look like tool calls (heuristic)
  // Look for JSON with common tool parameter names
  const jsonBlockPattern = /```(?:json)?\s*(\{[\s\S]*?\})\s*```/gi;
  while ((match = jsonBlockPattern.exec(text)) !== null) {
    try {
      const parsed = JSON.parse(match[1]);
      // Check if it looks like a tool call
      if (parsed.name && (parsed.arguments || parsed.input || parsed.parameters)) {
        extracted.push({
          name: parsed.name,
          arguments: parsed.arguments || parsed.input || parsed.parameters,
          source: "json_text",
        });
      }
    } catch (e) {
      // Continue
    }
  }

  // Pattern 5: Natural language tool intent extraction
  // Matches: "I'll use the Task tool with subagent_type=Explore"
  // Matches: "I will use the Read tool to read /path/to/file"
  // Matches: "Let me use the Bash tool to run ls -la"
  // The caller's own tool list is exact; this roster is the fallback for callers
  // that have none in hand. Natural-language extraction is the loosest pattern
  // here, so it keeps its own guard even though `keepOnlyRealTools` runs after.
  const knownTools =
    knownToolNames && knownToolNames.length > 0
      ? knownToolNames
      : [
          "Task",
          "Read",
          "Write",
          "Edit",
          "Bash",
          "Grep",
          "Glob",
          "WebFetch",
          "WebSearch",
          "ToolSearch",
        ];
  const nlPatterns = [
    // "I'll use the X tool with param=value" - ends with period, colon, newline, or end
    /(?:I(?:'ll| will| am going to)|Let me|Going to)\s+use\s+(?:the\s+)?(\w+)\s+tool\s+(?:with\s+)?(.+?)(?:[.:\n]|$)/gi,
    // "use X tool to do something"
    /use\s+(?:the\s+)?(\w+)\s+tool\s+(?:to\s+)?(.+?)(?:[.:\n]|$)/gi,
  ];

  for (const pattern of nlPatterns) {
    pattern.lastIndex = 0; // Reset regex state
    while ((match = pattern.exec(text)) !== null) {
      const toolName = match[1];
      const paramText = match[2];

      // Only extract if it's a known tool
      if (!knownTools.some((t) => t.toLowerCase() === toolName.toLowerCase())) {
        continue;
      }

      // Normalize tool name
      const normalizedToolName =
        knownTools.find((t) => t.toLowerCase() === toolName.toLowerCase()) || toolName;
      const args: Record<string, any> = {};

      // Extract key=value pairs
      const kvPattern = /(\w+)\s*=\s*["']?([^"',\s]+)["']?/g;
      let kvMatch;
      while ((kvMatch = kvPattern.exec(paramText)) !== null) {
        args[kvMatch[1]] = kvMatch[2];
      }

      // Extract quoted strings as potential file paths or commands
      const quotedPattern = /["']([^"']+)["']/g;
      let quotedMatch;
      const quotedValues: string[] = [];
      while ((quotedMatch = quotedPattern.exec(paramText)) !== null) {
        quotedValues.push(quotedMatch[1]);
      }

      // Tool-specific parameter extraction from natural language
      if (normalizedToolName === "Task") {
        // Look for subagent_type mentions
        if (!args.subagent_type) {
          const stMatch = paramText.match(/subagent_type\s*[=:]\s*["']?(\w+)["']?/i);
          if (stMatch) {
            args.subagent_type = stMatch[1];
          } else if (/explore|codebase|structure/i.test(paramText)) {
            args.subagent_type = "Explore";
          } else if (/plan|architect/i.test(paramText)) {
            args.subagent_type = "Plan";
          } else {
            args.subagent_type = "general-purpose";
          }
        }
        // Extract task intent as prompt
        if (!args.prompt) {
          // Use the text after "to" as the prompt
          const toMatch = paramText.match(/\bto\s+(.+)/i);
          if (toMatch) {
            args.prompt = toMatch[1].trim();
          } else {
            args.prompt = paramText.trim();
          }
        }
        if (!args.description) {
          args.description = (args.prompt || paramText).substring(0, 50).trim();
        }
      } else if (normalizedToolName === "Read") {
        // Extract file path
        if (!args.file_path) {
          if (quotedValues.length > 0) {
            args.file_path = quotedValues[0];
          } else {
            // Look for path-like strings
            const pathMatch = paramText.match(/(?:read|file)\s+([\/\w.-]+)/i);
            if (pathMatch) {
              args.file_path = pathMatch[1];
            }
          }
        }
      } else if (normalizedToolName === "Bash") {
        // Extract command
        if (!args.command) {
          if (quotedValues.length > 0) {
            args.command = quotedValues[0];
          } else {
            // Look for "run X" or "execute X"
            const cmdMatch = paramText.match(/(?:run|execute)\s+(.+)/i);
            if (cmdMatch) {
              args.command = cmdMatch[1].trim();
            }
          }
        }
        if (args.command && !args.description) {
          args.description = `Run ${args.command.split(" ")[0]} command`;
        }
      } else if (normalizedToolName === "Grep" || normalizedToolName === "Glob") {
        // Extract pattern
        if (!args.pattern) {
          if (quotedValues.length > 0) {
            args.pattern = quotedValues[0];
          } else {
            const searchMatch = paramText.match(/(?:search|find|look for)\s+(.+)/i);
            if (searchMatch) {
              args.pattern = searchMatch[1].trim();
            }
          }
        }
      }

      // Only add if we extracted meaningful arguments
      if (Object.keys(args).length > 0) {
        extracted.push({
          name: normalizedToolName,
          arguments: args,
          source: "inferred",
        });
        log(
          `[ToolRecovery] Extracted natural language tool intent: ${normalizedToolName} with args: ${JSON.stringify(args)}`
        );
      }
    }
  }

  return keepOnlyRealTools(extracted, knownToolNames, decodeToolName);
}

/**
 * Infer missing parameters for known tools
 */
export function inferMissingParameters(
  toolName: string,
  args: Record<string, any>,
  missingParams: string[],
  context?: string
): Record<string, any> {
  const inferred = { ...args };

  // Task tool inference
  if (toolName === "Task") {
    // Valid subagent types
    const validSubagentTypes = [
      "general-purpose",
      "Explore",
      "Plan",
      "claude-code-guide",
      "code-analysis:detective",
      "feature-dev:code-architect",
      "feature-dev:code-explorer",
      "feature-dev:code-reviewer",
    ];

    // Normalize subagent_type - models often use variations
    if (inferred.subagent_type) {
      const st = inferred.subagent_type.toLowerCase();
      // Map common variations to valid types
      if (st.includes("explore") || st.includes("codebase") || st.includes("file")) {
        inferred.subagent_type = "Explore";
      } else if (st.includes("plan") || st.includes("architect")) {
        inferred.subagent_type = "Plan";
      } else if (
        st.includes("analysis") ||
        st.includes("analyz") ||
        st.includes("config") ||
        st.includes("git") ||
        st.includes("test") ||
        st.includes("doc") ||
        st.includes("version")
      ) {
        inferred.subagent_type = "general-purpose";
      } else if (!validSubagentTypes.includes(inferred.subagent_type)) {
        log(
          `[ToolRecovery] Unknown subagent_type "${inferred.subagent_type}", mapping to general-purpose`
        );
        inferred.subagent_type = "general-purpose";
      }
    }

    if (missingParams.includes("subagent_type") && !inferred.subagent_type) {
      // Default to general-purpose if not specified
      inferred.subagent_type = "general-purpose";
      log(`[ToolRecovery] Inferred subagent_type: general-purpose`);
    }

    // Try to extract meaningful task description from context
    let extractedTask = "";
    if (context) {
      // Look for common patterns that indicate the model's intent
      const patterns = [
        /(?:I(?:'ll| will| need to| want to| am going to)|Let me|Going to)\s+([^.!?\n]+)/i,
        /(?:help you|assist with)\s+([^.!?\n]+)/i,
        /(?:explore|search|find|look for|investigate)\s+([^.!?\n]+)/i,
        /(?:implement|create|build|add|fix|update)\s+([^.!?\n]+)/i,
      ];
      for (const pattern of patterns) {
        const match = context.match(pattern);
        if (match && match[1] && match[1].length > 10) {
          extractedTask = match[1].trim();
          log(`[ToolRecovery] Extracted task from context: "${extractedTask.substring(0, 50)}..."`);
          break;
        }
      }
      // Fallback: use the last meaningful sentence as context
      if (!extractedTask && context.length > 20) {
        const sentences = context.split(/[.!?\n]+/).filter((s) => s.trim().length > 15);
        if (sentences.length > 0) {
          extractedTask = sentences[sentences.length - 1].trim();
        }
      }
    }

    if (missingParams.includes("prompt") && !inferred.prompt) {
      // Try to use description, task content, query, or extracted context
      // Some models use "query" instead of "prompt"
      if (inferred.query) {
        inferred.prompt = inferred.query;
        log(`[ToolRecovery] Mapped query -> prompt: "${inferred.query.substring(0, 50)}..."`);
      } else if (inferred.description && inferred.description !== "Execute task") {
        inferred.prompt = inferred.description;
      } else if (inferred.task) {
        inferred.prompt = inferred.task;
      } else if (extractedTask) {
        inferred.prompt = extractedTask;
      } else if (context && context.length > 20) {
        // Use the full context if nothing else works
        inferred.prompt = context.substring(0, 500).trim();
      }
      if (inferred.prompt) {
        log(`[ToolRecovery] Inferred prompt: "${inferred.prompt.substring(0, 50)}..."`);
      }
    }

    if (missingParams.includes("description") && !inferred.description) {
      // Generate description from prompt or extracted task
      if (inferred.prompt) {
        // Take first 50 chars of prompt as description
        inferred.description = inferred.prompt.substring(0, 50).replace(/\s+/g, " ").trim();
        if (inferred.description.length < inferred.prompt.length) {
          inferred.description += "...";
        }
      } else if (extractedTask) {
        inferred.description = extractedTask.substring(0, 50).trim();
      } else {
        inferred.description = "Execute task";
      }
      log(`[ToolRecovery] Inferred description: ${inferred.description}`);
    }
  }

  // Bash tool inference
  if (toolName === "Bash") {
    if (missingParams.includes("command") && !inferred.command) {
      // Check for common alternative parameter names
      inferred.command = inferred.cmd || inferred.shell || inferred.script || "";
    }
    if (missingParams.includes("description") && !inferred.description) {
      if (inferred.command) {
        // Generate description from command
        const cmd = inferred.command.split(" ")[0];
        inferred.description = `Run ${cmd} command`;
      }
    }
  }

  // Read tool inference
  if (toolName === "Read") {
    if (missingParams.includes("file_path") && !inferred.file_path) {
      inferred.file_path = inferred.path || inferred.file || inferred.filename || "";
    }
  }

  // Write tool inference
  if (toolName === "Write") {
    if (missingParams.includes("file_path") && !inferred.file_path) {
      inferred.file_path = inferred.path || inferred.file || inferred.filename || "";
    }
    if (missingParams.includes("content") && !inferred.content) {
      inferred.content = inferred.text || inferred.data || inferred.body || "";
    }
  }

  // Grep tool inference
  if (toolName === "Grep") {
    if (missingParams.includes("pattern") && !inferred.pattern) {
      inferred.pattern = inferred.query || inferred.search || inferred.regex || "";
    }
  }

  // Glob tool inference
  if (toolName === "Glob") {
    if (missingParams.includes("pattern") && !inferred.pattern) {
      inferred.pattern = inferred.glob || inferred.path || inferred.search || "**/*";
    }
  }

  // ToolSearch inference
  // max_results has a schema default of 5; query must be extracted from context
  if (toolName === "ToolSearch") {
    if (missingParams.includes("max_results") && inferred.max_results === undefined) {
      inferred.max_results = 5;
      log(`[ToolRecovery] Inferred max_results: 5 (default)`);
    }
    if (missingParams.includes("query") && !inferred.query) {
      inferred.query = inferred.search || inferred.keyword || inferred.tool || "";
      if (inferred.query) {
        log(`[ToolRecovery] Inferred ToolSearch query: "${inferred.query}"`);
      }
    }
  }

  return inferred;
}

/**
 * Generate a retry prompt with error feedback
 */
export function generateRetryPrompt(
  toolName: string,
  missingParams: string[],
  providedArgs: Record<string, any>,
  toolSchema?: ToolSchema
): string {
  let prompt = `Your previous tool call to "${toolName}" was incomplete. `;
  prompt += `Missing required parameters: ${missingParams.join(", ")}.\n\n`;

  if (toolSchema?.input_schema?.properties) {
    prompt += `The ${toolName} tool requires:\n`;
    for (const param of missingParams) {
      const propSchema = toolSchema.input_schema.properties[param];
      if (propSchema) {
        prompt += `- ${param}: ${propSchema.description || propSchema.type || "required"}\n`;
      } else {
        prompt += `- ${param}: required\n`;
      }
    }
    prompt += "\n";
  }

  prompt += `You provided: ${JSON.stringify(providedArgs, null, 2)}\n\n`;
  prompt += `Please try again with ALL required parameters included.`;

  return prompt;
}

/**
 * Check if a tool call can be repaired
 */
export function canRepairToolCall(
  toolName: string,
  args: Record<string, any>,
  missingParams: string[]
): boolean {
  // Check if we have enough context to infer the missing params
  const inferred = inferMissingParameters(toolName, args, missingParams);

  // Verify all missing params are now present
  for (const param of missingParams) {
    if (!inferred[param] || inferred[param] === "") {
      return false;
    }
  }

  return true;
}

/**
 * Get tool calling guidance to add to system prompt for local models
 */
export function getToolCallingGuidance(): string {
  return `
IMPORTANT TOOL CALLING INSTRUCTIONS:
When calling tools/functions, you MUST include ALL required parameters. Incomplete tool calls will fail.

For the Task tool, you MUST always provide:
- description: A short (3-5 word) description of the task
- prompt: The detailed task instructions
- subagent_type: The type of agent (e.g., "general-purpose", "Explore", "Plan")

For the Bash tool, you MUST always provide:
- command: The shell command to execute
- description: A brief description of what the command does

For file tools (Read, Write, Edit), always provide the full file_path.

For the ToolSearch tool, you MUST always provide:
- query: The search query string (keywords or "select:tool_name")
- max_results: Maximum number of results (default: 5)

Format your tool calls as valid JSON with all required fields populated.
`;
}

/**
 * Validate and potentially repair a tool call.
 *
 * `repaired: true` means, and only means, that a schema `default` was applied
 * or a supplied value was moved onto the key the schema declares (S4-b
 * 4a0948c) — never "invented" and never coercion alone. Coercion changes a
 * value's type, never whether the call would have succeeded, and `repaired`
 * drives a path in `openai-sse.ts` that supersedes an already-streamed tool
 * block with a second one — a flag that fires on ordinary valid calls would
 * mint duplicate blocks for nothing.
 *
 * Missing keys are measured with `missingRequired` — presence is KEY
 * PRESENCE, never truthiness: `""` is a present value a model may
 * legitimately mean (a live grok-4.6 turn emitted `Edit{new_string:""}` — a
 * deletion — and was rejected as "missing"). Our fork's per-tool inference
 * (`inferMissingParameters`) remains as a LAST RESORT after the upstream
 * cascade, because deleting it would strand calls our fleet has relied on;
 * anything it fills is schema-typed and shape-verified, but NOT marked
 * repaired — inferred values are not declared ones.
 */
export function validateAndRepairToolCall(
  toolName: string,
  argsStr: string,
  toolSchemas: ToolSchema[],
  textContent?: string
): {
  valid: boolean;
  args: Record<string, any>;
  repaired: boolean;
  missingParams: string[];
} {
  const schema = toolSchemas.find((t) => t.name === toolName);
  if (!schema?.input_schema) {
    return { valid: true, args: {}, repaired: false, missingParams: [] };
  }

  let parsedArgs: Record<string, any> = {};
  try {
    parsedArgs = argsStr ? JSON.parse(argsStr) : {};
  } catch (e) {
    // Try to extract from text if structured parsing failed
    if (textContent) {
      const extracted = extractToolCallsFromText(
        textContent,
        toolSchemas.map((t) => t.name),
        undefined,
        toolSchemas
      );
      const matching = extracted.find((tc) => tc.name === toolName);
      if (matching) {
        parsedArgs = matching.arguments;
        log(`[ToolRecovery] Extracted tool args from text for ${toolName}`);
      }
    }
  }

  const input = schema.input_schema as JsonSchemaNode;

  // Rename first — a value under a synonym has to land on the declared key
  // before anything asks whether that key is absent. Then defaults, which are
  // the client's own declaration. Then types, over the final set.
  const renamed = renameToDeclaredKeys(input, parsedArgs);
  const defaulted = applySchemaDefaults(input, renamed.args);
  const coerced = coerceToSchema(input, defaulted.args);
  let args = coerced.args as Record<string, any>;
  let repaired = renamed.renamed.length > 0 || defaulted.applied.length > 0;

  if (repaired) {
    log(
      `[ToolRecovery] ${toolName}: applied schema defaults [${defaulted.applied}] ` +
        `and key renames [${renamed.renamed}] — nothing was invented`
    );
  }
  if (coerced.coerced.length > 0) {
    log(`[ToolRecovery] ${toolName}: coerced to declared types [${coerced.coerced}]`);
  }

  let missingParams = missingRequired(input, args);

  if (missingParams.length > 0) {
    // Last resort: our fork's per-tool inference — kept, but never marked
    // repaired and never trusted blindly.
    const inferred = inferMissingParameters(toolName, args, missingParams, textContent);
    const stillMissing = missingRequired(input, inferred);
    if (stillMissing.length < missingParams.length) {
      args = inferred;
      missingParams = stillMissing;
      log(`[ToolRecovery] ${toolName}: inference filled [${missingParams.length ? missingParams : "none"} remaining] — last-resort path, not counted as repaired`);
    }
  }

  if (missingParams.length === 0) {
    return { valid: true, args, repaired, missingParams: [] };
  }

  return { valid: false, args, repaired: false, missingParams };
}
